import { owners, dependencies, numbers, money, artifact, approved, allApproved } from './proposal-model.mjs';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const e = escapeHtml;
const icon = file => `<img src="assets/${e(file)}" alt="">`;
const pill = (text, tone='') => `<span class="pill ${tone}">${text}</span>`;
const person = (owner, compact=false) => `<span class="avatar ${owner.id}">${owner.name[0]}</span><span class="identity"><b>${owner.name}</b><small>${compact?owner.department.split(' · ')[0]:owner.department}</small></span>`;
export const scenes = [
  {eyebrow:'01 / The individual win', title:'Everyone finished their part.', lead:'Sales, delivery, finance, legal and marketing have each used AI successfully.'},
  {eyebrow:'02 / An ordinary client request', title:'Then the client changed one thing.', lead:'Add Denver. Keep the same deadline. Show the added cost.'},
  {eyebrow:'03 / The work AI did not remove', title:'The work is done. The handoffs aren’t.', lead:'One client change. Four follow-ups for Leah, the proposal owner.'},
  {eyebrow:'04 / Replay the same change with Nine-67', title:'Keep the decisions. Connect the work.', lead:'Same request. Same people. Each approved answer reaches the next person automatically.'},
  {eyebrow:'05 / The company outcome', title:'One proposal. Ready for the customer.', lead:'The scope, staffing, price and terms now agree.'}
];
const localResults={sales:['Client scope','Austin · 90 days'],delivery:['Staffing plan','90-day delivery model'],finance:['Pricing model','$750,000 · 40% margin'],legal:['Engagement terms','Austin scope reviewed'],marketing:['Executive summary','Original narrative ready']};
const tools = owner => `<span class="tool">${icon(owner.icon)}${owner.ai}</span><span class="tool">${icon(owner.systemIcon)}${owner.system}</span>`;
export function roster(state){return owners.map(owner=>`<button class="roster-person ${state.scene===3&&approved(state,owner.id)?'approved':''}" data-detail="ai:${owner.id}" aria-label="Inspect ${owner.name}'s ${owner.ai} conversation"><span class="roster-id">${person(owner,true)}</span><span class="roster-tools">${tools(owner)}</span></button>`).join('');}
function firstScene(){return `<div class="stage-one"><div class="company-line"><span class="company-monogram">S</span><div><b>Summit Advisory Group</b><span>150 people · Professional services · Fictional example</span></div><div class="opportunity-chip">Northstar opportunity <b>$750,000</b></div></div><div class="five-outputs">${owners.map(owner=>`<button class="output-card" data-detail="ai:${owner.id}"><div class="person">${person(owner,true)}</div><div class="ai-label">${icon(owner.icon)}<b>${owner.ai}</b></div><div class="mini-document"><span class="document-type">${owner.file.split('.').at(-1).toUpperCase()}</span><h3>${localResults[owner.id][0]}</h3><p>${localResults[owner.id][1]}</p><span class="complete-label">✓ Reviewed &amp; complete</span></div><div class="system-source">${icon(owner.systemIcon)}<span>${owner.system}</span><small>View AI chat ↗</small></div></button>`).join('')}</div><div class="converge" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div><div class="unfinished-packet"><span class="completion-count">5<span>/ 5</span></span><div><small>CONTRIBUTIONS COMPLETE</small><h2>The proposal still needs someone<br>to bring it all together.</h2></div>${pill('Assembly + final review','amber')}</div></div>`;}
function secondScene(state){return `<div class="email-stage"><section class="outlook-window"><div class="app-chrome outlook">${icon('ms-outlook.svg')}<b>Outlook</b><span>Leah’s inbox</span></div><div class="mail-toolbar"><span>Inbox / Northstar Distribution</span><span>Reply ↶ &nbsp; Forward → &nbsp; ···</span></div><div class="email-subject"><small>MONDAY · CLIENT REQUEST</small><h2>RE: Operational improvement proposal</h2></div><div class="mail-person"><span class="avatar client">R</span><div><b>Rachel Ortiz</b><small>COO · Northstar Distribution → Leah</small></div><span>10:30 AM</span></div><div class="email-copy"><p>Hi Leah,</p><p>Please <mark>include Denver alongside Austin</mark> in the proposal. We’d like both locations covered within the <mark>same 90 days</mark>.</p><p>Show the additional staffing and cost. We still need the proposal by Friday.</p><p>Thanks for coordinating this,<br><b>Rachel</b></p></div></section><div class="email-response"><span class="response-eyebrow">THE CUSTOMER FEELS TAKEN CARE OF</span><div class="response-label">${icon('openai.svg')}ChatGPT-assisted reply · Leah / Sales</div><p>“Got it, Rachel. I’ll coordinate the revised scope, staffing, price and terms, then send you one consistent proposal.”</p><div class="requirement-tokens"><span class="requirement-chip">+ Denver</span><span>90 days</span><span>Proposal Friday</span></div><div class="reply-signature"><span class="avatar sales">L</span><span><b>Leah</b><small>Sales · Proposal owner</small></span><span class="reply-status">Acknowledged ✓</span></div></div></div>`;}
const manualBeats=[
 {from:'delivery',to:'finance',clock:'Monday · Delivery replies',heading:'Sam has the staffing answer.',fact:'+30 consultant-days',message:'“Denver needs 30 additional days. I’ve checked parallel staffing; the plan can stay at 90 days.”',source:'Delivery plan v2 · Sam reviewed',leah:'“Priya, use Sam’s additional 30 days to update the pricing. The duration is still 90 days.”',next:'Finance needs the current staffing basis.',burden:'Copy the approved estimate into the next conversation.',value:'30 days'},
 {from:'finance',to:'legal',clock:'Tuesday · Pricing replies',heading:'Now the price has to travel.',fact:'$810,000 total fee',message:'“Pricing updated: +$60,000 fee, +$45,000 cost. Revised total $810,000. Margin 38.9%.”',source:'Pricing model v2 · Priya reviewed',leah:'“Alex, review the terms for Austin + Denver, 90 days and $810,000. Here is the latest pricing file.”',next:'Legal needs the approved scope and price together.',burden:'Carry the new fee and scope into the legal review.',value:'$810,000'},
 {from:'legal',to:'marketing',clock:'Wednesday · Terms return',heading:'Which versions go in the proposal?',fact:'Two locations. One set of terms.',message:'“Terms reviewed for Austin + Denver, 90 days and the $810,000 fee. Use this version in the packet.”',source:'Terms v2 · Alex reviewed',leah:'“Maya, use delivery v2, pricing v2 and these terms. Please replace the earlier summary.”',next:'Marketing needs the approved versions of all sections.',burden:'Find the latest files and carry the decisions into assembly.',value:'Approved v2 files'},
 {from:'marketing',to:'leadership',clock:'Wednesday · Assembly returns',heading:'Leah still owns the last mile.',fact:'One assembled draft',message:'“The revised summary and sections are assembled. Please check the packet and route it for final approval.”',source:'Proposal v2 · Maya assembled',leah:'“Here is the consolidated packet and each owner’s review. Please approve the final proposal for release.”',next:'Leadership still needs one decision-ready packet.',burden:'Reconstruct the approval trail and chase final sign-off.',value:'Review packet'}
];
function missingChange(){return `<div class="stage-empty"><span class="requirement-chip">+ Denver</span><h2>Start with the client’s change.</h2><p>The original Austin contributions are complete. Load the same Denver request to continue this walkthrough.</p><button class="primary" data-action="change">Load Rachel’s request →</button></div>`;}
function revisionText(state,text){const n=numbers(state);return text.replace(/Austin \+ Denver/g,state.sites.join(' + ')).replace(/both (sites|locations)/g,`all ${state.sites.length} $1`).replace(/Two locations|two-location/g,`${state.sites.length} locations`).replace(/330/g,String(n.days)).replace(/\+?30(?= (?:additional )?(?:consultant-)?days)/g,match=>`${match.startsWith('+')?'+':''}${n.days-300}`).replace(/\$810,000/g,money(n.fee)).replace(/\$60,000/g,money(n.fee-750000)).replace(/\$45,000/g,money(n.cost-450000)).replace(/38\.9%/g,`${n.margin}%`).replace(/v2/g,`v${state.revision}`);}
function revisedBeat(state){return Object.fromEntries(Object.entries(manualBeats[Math.min(state.manualCount,3)]).map(([key,value])=>[key,revisionText(state,value)]));}
function manualHandoff(state){if(!state.changed)return missingChange();const beat=revisedBeat(state);const from=owners.find(row=>row.id===beat.from);const to=owners.find(row=>row.id===beat.to)||{id:'leadership',name:'Leadership',department:'Final authorization'};return `<div class="manual-stage"><div class="beat-header"><span>${beat.clock}</span><span class="requirement-chip">${e(state.sites.slice(1).join(' + '))} added · same 90 days</span><small>Illustrative story timeline</small></div><div class="handoff-visual"><section class="source-app"><div class="app-chrome ${from.ai.toLowerCase()}">${icon(from.icon)}<b>${from.ai}</b><span>${from.name} · ${from.department.split(' · ')[0]}</span></div><div class="source-content"><small>AI-ASSISTED WORK, REVIEWED BY ${from.name.toUpperCase()}</small><h2>${beat.fact}</h2><p>${beat.message}</p><div class="source-receipt">${icon(from.systemIcon)}<span>${beat.source}</span></div></div></section><div class="human-bridge"><span class="bridge-line"></span><span class="avatar sales">L</span><b>Leah</b><small>copies + coordinates</small><span class="bridge-line"></span></div><section class="destination-app"><div class="app-chrome teams">${icon('ms-teams.svg')}<b>Teams</b><span>Leah → ${to.name}</span></div><div class="destination-content"><div class="person">${person(to,true)}</div><div class="teams-bubble"><small>Leah · Proposal owner</small><p>${beat.leah}</p></div><div class="waiting-label">◷ ${beat.next}</div></div></section></div><div class="manual-work-caption"><div><small>THE EXTRA WORK</small><h3>${beat.burden}</h3></div><span class="carried-fact">${beat.value}</span></div><div class="beat-progress">${manualBeats.map((row,i)=>`<button data-manual-beat="${i}" class="${i===Math.min(state.manualCount,3)?'current':i<state.manualCount?'done':''}"><span>${i<state.manualCount?'✓':i+1}</span>${['Effort → pricing','Price → terms','Terms → assembly','Packet → approval'][i]}</button>`).join('')}</div></div>`;}
function manualScene(state){
 if(!state.changed)return missingChange();
 const n=numbers(state);
 const steps=[
  {name:'Sam',dept:'Delivery',ai:'Copilot',icon:'copilot.webp',system:'Jira',result:`+${n.days-300} consultant-days`,next:'Send the estimate to Finance'},
  {name:'Priya',dept:'Finance',ai:'ChatGPT',icon:'openai.svg',system:'Excel',result:`${money(n.fee)} proposed fee`,next:'Send the price to Legal'},
  {name:'Alex',dept:'Legal',ai:'Claude',icon:'claude.svg',system:'Word',result:`Terms reviewed · v${state.revision}`,next:'Get the approved files to Marketing'},
  {name:'Maya',dept:'Marketing',ai:'Copilot',icon:'copilot.webp',system:'SharePoint',result:'Proposal assembled',next:'Collect the final approval'}
 ];
 return `<div class="handoff-ledger"><div class="ledger-labels"><span>THE TEAM COMPLETES ITS WORK</span><span>LEAH STILL HAS TO…</span></div>${steps.map((step,i)=>`<button class="ledger-row" data-detail="handoff:${i}" aria-label="View ${step.name}'s handoff"><span class="ledger-owner"><b>${step.name} <small>· ${step.dept}</small></b><span>${icon(step.icon)}${step.ai} · ${step.system}</span></span><strong>${step.result}</strong><span class="ledger-next">${step.next}<span aria-hidden="true">↗</span></span></button>`).join('')}<p class="ledger-takeaway">Everyone used AI. <strong>Leah is still the workflow.</strong></p></div>`;
}
const handoffFacts={sales:{headline:'The requirement is attached to the work.',fact:'Austin + Denver',source:'Leah confirms Rachel’s request',destination:'Sam receives scope + resource-plan context',quote:'“Both locations, 90 days, additional cost requested. This is the shared requirement for the revision.”'},delivery:{headline:'Sam’s decision becomes Priya’s input.',fact:'+30 consultant-days',source:'Sam approves delivery plan v2',destination:'Priya’s pricing review gets the approved effort',quote:'“Parallel staffing is confirmed. Add 30 consultant-days without extending the 90-day plan.”'},finance:{headline:'The approved price flows into the terms.',fact:'$810,000 proposed fee',source:'Priya approves pricing model v2',destination:'Alex receives scope + fee; Maya’s draft refreshes',quote:'“Added cost $45,000; added fee $60,000. Revised fee $810,000 and margin 38.9%, approved.”'},legal:{headline:'The commitments stay attached to the numbers.',fact:'Two locations · 90 days',source:'Alex approves terms v2',destination:'Maya receives the approved terms and source versions',quote:'“The revised locations, fee and delivery assumptions are reflected in the terms. This version is approved.”'},marketing:{headline:'One packet, built from the approved pieces.',fact:'Proposal v2 assembled',source:'Maya reviews the final narrative',destination:'Leah receives the complete packet + decision trail',quote:'“The summary matches the approved scope, staffing, price and terms. The packet is ready for final authorization.”'}};
function connectedScene(state){if(!state.changed)return missingChange();const done=owners.filter(row=>approved(state,row.id));const active=done.at(-1);const facts=active?Object.fromEntries(Object.entries(handoffFacts[active.id]).map(([key,value])=>[key,revisionText(state,value)])):null;const readyReview=done.length===5;return `<div class="connected-stage"><div class="coordinator-head"><span class="n67-icon">N</span><div><b>Nine-67 · Proposal coordinator</b><small>One requirement · One approval trail</small></div><span class="requirement-chip">${e(state.sites.slice(1).join(' + '))} added · same 90 days</span>${pill(state.ready?'Verified':state.playing?'Playing sample responses':readyReview?'Ready for final decision':state.analyzed?'Owners routed':'Same client request',state.ready?'green':'')}</div><div class="work-path">${owners.map((owner,i)=>`<div class="path-item ${approved(state,owner.id)?'done':state.analyzed?'routed':''}"><span class="path-avatar">${icon(owner.icon)}${approved(state,owner.id)?'<i>✓</i>':''}</span><b>${owner.name}</b><small>${owner.department.split(' · ')[0]}</small><span>${approved(state,owner.id)?'v'+state.revision+' approved':state.analyzed?'Review routed':'Original complete'}</span></div>${i<4?'<div class="path-arrow" aria-hidden="true">→</div>':''}`).join('')}</div><div class="orchestration-proof">${!state.analyzed?`<div class="trace-intro"><small>THE SAME REQUEST, CONNECTED</small><h2>Denver changes the plan.<br>The workflow carries it forward.</h2><p>Scope → Staffing → Pricing → Terms → Proposal</p><div class="source-mini">${icon('ms-outlook.svg')}Rachel’s request <span>→</span>${icon('ms-word.svg')}Five affected sections</div></div>`:readyReview?`<div class="packet-review"><div><small>${state.ready?'VERIFIED CUSTOMER PACKET':'LEAH’S ASSEMBLED REVIEW PACKET'}</small><h2>${state.ready?'The decisions are now reflected in the systems.':'One decision-ready proposal.'}</h2><p>${state.ready?'SharePoint, HubSpot and Jira agree with the approved revision.':'Five named owners reviewed the same revision. Leadership authorizes the assembled commitment before updates are applied.'}</p></div><div class="packet-facts"><div><small>LOCATIONS</small><b>${e(state.sites.join(' + '))}</b></div><div><small>DURATION</small><b>90 days</b></div><div><small>FEE</small><b>${money(numbers(state).fee)}</b></div><div><small>EVIDENCE</small><b>5 owner decisions · v${state.revision}</b></div></div></div>`:facts?`<div class="flow-moment"><div class="approved-fact"><small>HUMAN DECISION · SIMULATED RESPONSE</small><h2>${facts.fact}</h2><p>${facts.quote}</p><span class="source-receipt">✓ ${facts.source}</span></div><div class="auto-arrow"><span>→</span><small>carried automatically</small></div><div class="next-context"><small>NEXT TASK PREPARED</small><h3>${facts.destination}</h3><div class="context-packet"><b>Attached to the handoff</b><span>Client requirement v${state.revision}</span><span>Approved source + named decision</span><span>Updated draft for the next owner</span></div></div></div>`:`<div class="trace-intro"><small>THE AFFECTED WORK IS NOW CONNECTED</small><h2>The right context.<br>The right owner. The next step.</h2><p>Play the recorded example responses. Each person still makes their decision; the coordinator carries the approved result onward.</p><div class="scope-evidence">${pill('Scope review routed to Leah')}${pill('Staffing → pricing → terms → summary')}</div></div>`}</div><div class="automation-caption"><span>${state.playing?'● Simulated named-owner responses are playing':readyReview?'✓ Owners retain judgment. The workflow carries their decisions.':'Sample workflow · AI does not approve its own work'}</span>${state.playing?'<button class="text-button" data-action="pause">Pause</button>':''}<button class="text-button" data-detail="build">What Nine-67 builds ↗</button></div><div class="write-rail">${['SharePoint','HubSpot','Jira'].map((name,i)=>`<span class="${state.writes[name]===state.revision?'verified':''}">${icon(['ms-sharepoint.svg','hubspot.svg','jira.svg'][i])}<b>${name}</b><small>${state.writes[name]===state.revision?'✓ Saved + verified':'Awaiting approved update'}</small></span>`).join('')}<button data-detail="exceptions" class="text-button">Test an exception ↗</button></div>${state.notice?`<p class="inline-notice" role="status">${e(state.notice)}</p>`:''}</div>`;}
function finalScene(state){if(!state.ready)return `<div class="stage-empty"><span class="packet-icon">▱</span><h2>The final packet still needs its decisions.</h2><p>Return to the connected workflow to play the owner reviews and verify the updates.</p><button data-goto="3" class="primary">Continue the workflow →</button></div>`;const n=numbers(state);return `<div class="finish-stage"><section class="proposal-cover"><div class="cover-brand">SUMMIT<br><span>ADVISORY GROUP</span></div><div class="cover-art" aria-hidden="true"><span></span><span></span><span></span></div><small>PREPARED FOR NORTHSTAR DISTRIBUTION</small><h2>Operational<br>improvement.<br>${state.sites.length} locations.<br>One plan.</h2><div class="cover-facts"><span>${money(n.fee)}</span><span>90 days</span></div><div class="cover-status">✓ Revision ${state.revision} · Ready for Leah’s final send review</div></section><div class="finish-evidence"><div class="finished-facts"><div><small>SCOPE</small><b>${e(state.sites.join(' + '))}</b><span>Matches Rachel’s request</span></div><div><small>DELIVERY + PRICE</small><b>${n.days} days · ${money(n.fee)}</b><span>Reviewed by Sam + Priya</span></div><div><small>TERMS + NARRATIVE</small><b>Same approved revision</b><span>Reviewed by Alex + Maya</span></div></div><section class="final-email"><div class="app-chrome outlook">${icon('ms-outlook.svg')}<b>Leah → Rachel</b><span>Draft · not sent</span></div><div class="final-email-subject"><b>Your updated proposal</b><small>To: Rachel Ortiz · Northstar Distribution</small></div><p>“Your updated proposal covers ${e(state.sites.join(' + '))} within 90 days. The ${money(n.fee)} fee, staffing plan and terms have been reviewed together. We’re ready to walk your team through the complete plan.”</p></section><div class="finish-thesis"><h3>We connected their work,<br>information and decisions.</h3><p>Five completed tasks became one completed customer outcome.</p></div><div class="finish-actions"><button data-detail="assessment" class="primary">Find your manual handoffs →</button><button data-action="download" class="text-button">Download sample summary ↗</button></div></div></div>`;}
export function renderScene(state){return [firstScene,secondScene,manualScene,connectedScene,finalScene][state.scene](state);}
export function renderSidebar(state){let title,who,done,gap,quote;const count=owners.filter(row=>approved(state,row.id)).length;if(state.scene===0){title='The individual win';who='Five people + their AI';done='Each original contribution is complete for Austin.';gap='Leah still owns assembly and the final review.';quote='“These are capable people. Every one used AI successfully.”';}else if(state.scene===1){title='A normal change';who='Rachel → Leah';done='Add Denver. Keep 90 days. Show the cost.';gap='The same requirement must now travel through five contributions.';quote='“Nobody made a mistake. The client changed the requirement.”';}else if(state.scene===2){const b=revisedBeat(state);title='Leah is the connector';who='Leah · Proposal owner';done=b.source+'.';gap=b.burden;quote='“The AI did its job. Leah is still carrying the answer.”';}else if(state.scene===3){title='The workflow carries it';who='Same people. Same AI.';done=count?`${count} / 5 recorded owner decisions. Each result prepares the next task.`:'The requirement and affected source records are connected.';gap=state.ready?'Approved updates are saved and verified.':state.playing?'People decide. The workflow routes, follows up and updates.':'No manual copying between the review steps.';quote='“What disappears is Leah carrying every answer into the next conversation.”';}else{title=state.ready?'The company outcome':'Readiness is earned';who='Leah → customer';done=state.ready?'One aligned proposal, with decisions and verified records attached.':'The packet must pass the same approval and verification gates.';gap=state.ready?'The customer can evaluate one complete commitment.':'Continue the connected review to finish.';quote='“That is how individual productivity becomes completed company work.”';}return `<div class="rail-heading"><small>WHAT’S HAPPENING</small><h2>${title}</h2></div><div class="rail-person"><span class="avatar sales">L</span><div><b>${who}</b><small>Leah coordinates the proposal</small></div></div><div class="rail-block"><small>WHAT JUST HAPPENED</small><p>${done}</p></div><div class="rail-block rail-key ${state.scene>=3?'solution':''}"><small>${state.scene>=3?'WHAT CHANGED':'WHAT STILL TAKES WORK'}</small><p>${gap}</p></div><blockquote>${quote}</blockquote>`;}
export function primaryAction(state){if(state.scene===0)return {label:'See the client request →',action:'next'};if(state.scene===1)return {label:'See the manual work →',action:'start-manual'};if(state.scene===2)return {label:'Now connect the same work →',action:'next'};if(state.scene===3){if(!state.changed)return {label:'Load the same client request →',action:'change'};if(!state.analyzed)return {label:'Run the connected workflow →',action:'run'};if(state.playing)return {label:'Next owner response →',action:'advance-run'};if(!owners.every(row=>approved(state,row.id)))return {label:state.runPhase==='paused'?'Resume owner responses →':'Run the connected workflow →',action:'run'};if(!state.ready)return {label:state.notice?'Retry the approved updates →':'Approve and prepare the proposal →',action:'release'};return {label:'See the customer-ready proposal →',action:'next'};}return {label:state.ready?'Find your manual handoffs →':'Continue the connected review →',action:state.ready?'assessment':'return-review'};}
const practicalChats={
 sales:['Update the scope from Rachel’s revised requirement for Austin + Denver.','Prepared the revised two-location scope with the same 90-day duration. Additional staffing and cost need owner review.','I confirmed the request. Draft the delivery handoff with the source attached.','“Austin + Denver, same 90 days. Please review the delivery impact against requirement v2, then pass the approved effort to finance.”'],
 delivery:['Add Denver to the delivery draft without extending the 90 days. Use the existing staffing model.','The draft needs 30 additional consultant-days in parallel. I’ve prepared the revised staffing plan; review the resource allocation.','I’ve checked the allocation. Draft my reply to Leah.','“Delivery can support both sites in 90 days with 330 consultant-days. Finance should price the additional 30 days.”'],
 finance:['Use Sam’s approved additional 30 days to revise the model.','At $1,500 loaded cost per day, the added cost is $45,000. The sample fee increase is $60,000: $810,000 total, 38.9% margin.','I’ve reviewed the model. Draft the handoff with the assumptions.','“Pricing approved for Austin + Denver: $810,000, using Sam’s 330-day plan. Please carry the locations, duration and fee together into the terms.”'],
 legal:['Update the draft terms using the approved two-location scope and pricing model.','The draft now includes Austin + Denver, the $810,000 fee and 90-day duration, with the client-access and change-control provisions.','I reviewed those commitments. Draft my reply for proposal assembly.','“Terms v2 approved against the revised scope and price. Use this version with delivery v2 and pricing v2.”'],
 marketing:['Assemble the summary from the approved scope, staffing, price and terms.','The draft summary reflects Austin + Denver, the 90-day plan and $810,000 fee. Its sections reference the approved v2 sources.','I’ve reviewed the narrative. Draft my handoff to Leah.','“Proposal v2 assembled from the approved sections. The packet includes the current source versions and is ready for final authorization.”']};
export function renderDetail(state,key){if(key==='explanation')return {title:'Why this matters',html:renderSidebar(state)};if(key.startsWith('handoff:'))return {title:'The manual handoff',html:manualHandoff({...state,manualCount:Math.max(0,Math.min(3,Number(key.split(':')[1])||0))})};if(key.startsWith('ai:')){const id=key.split(':')[1];const owner=owners.find(row=>row.id===id)||owners[0];const original=state.scene===0||!state.changed;const chat=original?[`Prepare my ${owner.deliverable.toLowerCase()} for the original Austin requirement.`,`Draft prepared for Austin and the 90-day project. ${localResults[owner.id][1]}.`,`I’ve reviewed it. Draft the handoff to ${owner.id==='sales'?'the delivery team':'Leah'}.`,`“${owner.deliverable} complete for Austin. The reviewed source is attached for the proposal packet.”`]:practicalChats[owner.id].map(line=>revisionText(state,line));return {title:`${owner.name} · ${owner.department}`,html:`<div class="detail-tools">${tools(owner)}${pill(original?'Original requirement':'Revised requirement')}</div><div class="ai-detail ${owner.ai.toLowerCase()}"><div class="app-chrome">${icon(owner.icon)}<b>${owner.ai}</b><span>Illustrative conversation</span></div>${chat.map((line,i)=>`<div class="chat-turn ${i%2?'assistant':'user'}"><small>${i%2?owner.ai:owner.name}</small><p>${i===3?`<mark>${e(line)}</mark>`:e(line)}</p></div>`).join('')}</div><div class="source-preview"><small>CONNECTED WORK PRODUCT · ${owner.file}</small><h3>${owner.deliverable}</h3><p>${e(artifact(state,owner.id,original)[2])}</p><p>${e(artifact(state,owner.id,original)[3])}</p></div><p class="detail-note">The coordinator connects permitted business records and work products. It does not silently read private AI conversations.</p>`};}if(key==='build')return {title:'What Nine-67 would build',html:`<div class="build-detail-grid"><section><span>01</span><h3>Connected sources</h3><p>Outlook request, HubSpot scope, Jira delivery plan, Excel pricing, Word terms and the SharePoint proposal. Use authorized integrations; route unsupported steps to an owner.</p></section><section><span>02</span><h3>One versioned requirement</h3><p>Keep locations, timeline, commitments, evidence links and source versions attached to the same opportunity. A changed source reopens the affected decisions.</p></section><section><span>03</span><h3>A workflow that continues</h3><p>Approved effort feeds pricing. Approved price feeds terms. Approved sections feed assembly. A durable queue tracks owners, reminders, replies and escalation.</p></section><section><span>04</span><h3>Verified completion</h3><p>People approve judgment. The system checks consistency, applies authorized updates, retries safely and verifies the saved result before reporting readiness.</p></section></div><div class="build-bottom"><b>Start with one workflow.</b><p>Replay sample cases, test exceptions, pilot approved updates, then measure actual coordination time, waiting and rework. The current screen is a working prototype with simulated integrations.</p></div>`};if(key==='exceptions')return {title:'Test the workflow, not just the happy path',html:`<p class="detail-intro">Choose an exception before the final authorization. Release must remain held until the records and decisions are consistent.</p><label class="fault-label">Simulated condition<select id="fault" ${state.ready?'disabled':''}><option value="none" ${state.fault==='none'?'selected':''}>No fault</option><option value="crm" ${state.fault==='crm'?'selected':''}>HubSpot update fails</option><option value="revision" ${state.fault==='revision'?'selected':''}>New client revision arrives before release</option></select></label><ul class="exception-list"><li><b>Failed write:</b> record partial completion, hold release, retry only the unfinished update.</li><li><b>Changed requirement:</b> invalidate stale approvals, reconnect the new revision and rerun the affected review.</li><li><b>Missing decision:</b> keep the packet held. The demo never substitutes an AI response for an owner’s authorization.</li></ul><p class="detail-note">${e(state.notice||'The final button plays a leadership decision and simulated writes. No actual approval or external update is performed.')}</p><button class="secondary" data-detail="audit">Inspect the decision history →</button>`};if(key==='audit')return {title:'Decisions stay attached to the work',html:`<ol class="audit-list">${state.audit.map(row=>`<li><small>#${row.sequence} · revision ${row.revision}</small><p>${e(row.message)}</p></li>`).join('')||'<li>No review events yet.</li>'}</ol>`};if(key==='assessment')return {title:'Find your manual handoffs.',html:`<div class="assessment-detail"><p class="eyebrow">COMPLIMENTARY WORKFLOW ASSESSMENT</p><h2>Where does everyone finish their part,<br>but the customer still waits?</h2><p>A working session with Suuchi and Josh. Bring one workflow. Map the systems, decisions, owners and handoffs. Identify where AI can help, and choose one real baseline metric.</p><div class="assessment-people"><p><b>Suuchi Ramesh</b><span>CEO / Forward Deployed Engineer</span></p><p><b>Josh Lee</b><span>COO / Forward Deployed Engineer</span></p></div><div id="booking-content"><strong>Type “assessment” and your workflow in chat.</strong></div><small>Scheduled separately after the webinar.</small></div>`};return {title:'About this demo',html:'<p>Summit Advisory Group, the people, documents, figures and events are fictional. AI conversations, owner responses, approvals, file imports and system writes are simulated. The interactive workflow gates, revision handling, safe retry and downloadable HTML summary run locally. No client message is sent. No quantified ROI saving is claimed.</p>'};}
